import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry matmul_nn_f32(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N_param
)
    .reqntid 32, 32, 1
    .maxnreg 63
{
    .reg .pred %pA, %pB, %pRowIn, %pColIn, %pTCond, %pKCond;
    .reg .b32 %rN, %rRow, %rCol, %rTx, %rTy, %rBx, %rBy, %rBDx, %rBDy, %rTiles, %rT, %rTmp1, %rTmp2, %rK, %rKcol, %rKrow, %rIndex;
    .reg .b64 %A, %B, %C, %addr, %addr2, %sA_base, %sB_base, %off64, %tmp64;
    .reg .f32 %sum, %aval, %bval, %zero;
    .shared .align 4 .b8 sA[4096];
    .shared .align 4 .b8 sB[4096];
    ld.param.u64 %A, [A_ptr];
    ld.param.u64 %B, [B_ptr];
    ld.param.u64 %C, [C_ptr];
    ld.param.u32 %rN, [N_param];
    // Convert incoming pointers to global address space
    cvta.to.global.u64 %A, %A;
    cvta.to.global.u64 %B, %B;
    cvta.to.global.u64 %C, %C;
    mov.u32 %rTx, %tid.x;
    mov.u32 %rTy, %tid.y;
    mov.u32 %rBx, %ctaid.x;
    mov.u32 %rBy, %ctaid.y;
    mov.u32 %rBDx, %ntid.x;
    mov.u32 %rBDy, %ntid.y;
    mad.lo.s32 %rCol, %rBx, %rBDx, %rTx;
    mad.lo.s32 %rRow, %rBy, %rBDy, %rTy;
    mov.f32 %sum, 0f00000000;
    mov.f32 %zero, 0f00000000;
    add.u32 %rTmp1, %rN, 31;
    shr.u32 %rTiles, %rTmp1, 5;
    // Take shared-memory base addresses directly
    mov.u64 %sA_base, sA;
    mov.u64 %sB_base, sB;
    mov.u32 %rT, 0;
TILE_LOOP:
    setp.ge.u32 %pTCond, %rT, %rTiles;
    @%pTCond bra TILE_END;
    shl.b32 %rKcol, %rT, 5;
    add.u32 %rKcol, %rKcol, %rTx;
    shl.b32 %rKrow, %rT, 5;
    add.u32 %rKrow, %rKrow, %rTy;
    setp.lt.u32 %pRowIn, %rRow, %rN;
    setp.lt.u32 %pColIn, %rCol, %rN;
    setp.lt.u32 %pA, %rKcol, %rN;
    and.pred %pA, %pA, %pRowIn;
    setp.lt.u32 %pB, %rKrow, %rN;
    and.pred %pB, %pB, %pColIn;
    @%pA bra LOAD_A;
    mov.f32 %aval, %zero;
    bra POST_LOAD_A;
LOAD_A:
    mul.wide.u32 %off64, %rRow, %rN;
    cvt.u64.u32 %tmp64, %rKcol;
    add.u64 %off64, %off64, %tmp64;
    shl.b64 %off64, %off64, 2;
    add.u64 %addr, %A, %off64;
    ld.global.f32 %aval, [%addr];
POST_LOAD_A:
    @%pB bra LOAD_B;
    mov.f32 %bval, %zero;
    bra POST_LOAD_B;
LOAD_B:
    mul.wide.u32 %off64, %rKrow, %rN;
    cvt.u64.u32 %tmp64, %rCol;
    add.u64 %off64, %off64, %tmp64;
    shl.b64 %off64, %off64, 2;
    add.u64 %addr2, %B, %off64;
    ld.global.f32 %bval, [%addr2];
POST_LOAD_B:
    shl.b32 %rTmp1, %rTy, 5;
    add.u32 %rIndex, %rTmp1, %rTx;
    cvt.u64.u32 %off64, %rIndex;
    shl.b64 %off64, %off64, 2;
    add.u64 %addr, %sA_base, %off64;
    st.shared.f32 [%addr], %aval;
    cvt.u64.u32 %off64, %rIndex;
    shl.b64 %off64, %off64, 2;
    add.u64 %addr, %sB_base, %off64;
    st.shared.f32 [%addr], %bval;
    bar.sync 0;
    mov.u32 %rK, 0;
    .pragma "nounroll";
K_LOOP:
    setp.ge.u32 %pKCond, %rK, 32;
    @%pKCond bra K_END;
    shl.b32 %rTmp1, %rTy, 5;
    add.u32 %rTmp1, %rTmp1, %rK;
    cvt.u64.u32 %off64, %rTmp1;
    shl.b64 %off64, %off64, 2;
    add.u64 %addr, %sA_base, %off64;
    ld.shared.f32 %aval, [%addr];
    shl.b32 %rTmp2, %rK, 5;
    add.u32 %rTmp2, %rTmp2, %rTx;
    cvt.u64.u32 %off64, %rTmp2;
    shl.b64 %off64, %off64, 2;
    add.u64 %addr, %sB_base, %off64;
    ld.shared.f32 %bval, [%addr];
    fma.rn.f32 %sum, %aval, %bval, %sum;
    add.u32 %rK, %rK, 1;
    bra K_LOOP;
K_END:
    bar.sync 0;
    add.u32 %rT, %rT, 1;
    bra TILE_LOOP;
TILE_END:
    and.pred %pA, %pRowIn, %pColIn;
    @!%pA bra STORE_END;
    mul.wide.u32 %off64, %rRow, %rN;
    cvt.u64.u32 %tmp64, %rCol;
    add.u64 %off64, %off64, %tmp64;
    shl.b64 %off64, %off64, 2;
    add.u64 %addr, %C, %off64;
    st.global.f32 [%addr], %sum;
STORE_END:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_nn_f32")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 supported"
        assert A.device.type == "cuda" and B.device == A.device, "Tensors must be on the same CUDA device"
        assert A.dim() == 2 and B.dim() == 2 and A.shape[0] == A.shape[1] == B.shape[0] == B.shape[1], "Inputs must be square NxN"
        N = A.shape[0]
        C = torch.empty((N, N), device=A.device, dtype=A.dtype)

        block_x, block_y = 32, 32
        grid_x = (N + block_x - 1) // block_x
        grid_y = (N + block_y - 1) // block_y

        module = _get_ptx_module()
        module.launch(
            "matmul_nn_f32",
            grid=(grid_x, grid_y, 1),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, u32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

